var names = new[]{"Processing","Cultivation","Storage"};
var art = UnityEditor.AssetDatabase.LoadAssetAtPath<MobileGame.Presentation.LaboratoryArtAssets>(MobileGame.Foundation.Editor.LaboratoryUiAssetBuilder.ArtPath);
var entries = new UnityEditor.SerializedObject(art).FindProperty("facilities");
if(entries.arraySize!=3) throw new System.Exception("Expected all three bindings");
var result = new System.Collections.Generic.List<object>();
for(var k=0;k<3;k++) {
 var name=names[k]; var path="Assets/Sprites/Facility/"+name+"/"+name+".png";
 var sprites = UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path).OfType<UnityEngine.Sprite>().ToArray();
 var frames=entries.GetArrayElementAtIndex(k).FindPropertyRelative("frames");
 if(sprites.Length!=16 || frames.arraySize!=16 || Enumerable.Range(0,16).Any(i=>frames.GetArrayElementAtIndex(i).objectReferenceValue==null)) throw new System.Exception("Incomplete "+name);
 var definition = UnityEditor.AssetDatabase.LoadAssetAtPath<MobileGame.Foundation.FacilityDefinition>("Assets/SO/Facility/"+name+".asset");
 var icon=new UnityEditor.SerializedObject(definition).FindProperty("icon").objectReferenceValue;
 if(icon!=frames.GetArrayElementAtIndex(0).objectReferenceValue) throw new System.Exception("Missing icon "+name);
 var importer=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(path);
 result.Add(new { name,path,guid=UnityEditor.AssetDatabase.AssetPathToGUID(path),frames=sprites.Length,iconMatches=true,ppu=importer.spritePixelsPerUnit,filter=importer.filterMode.ToString(),compression=importer.textureCompression.ToString(),readable=importer.isReadable,mipmaps=importer.mipmapEnabled });
}
return new { utc=System.DateTime.UtcNow.ToString("o"), play=UnityEditor.EditorApplication.isPlaying,ready=true,assets=result };
